<script lang="ts">
  import {tick,untrack} from 'svelte';
  import {page} from '$app/state';
  import {goto,refreshAll,beforeNavigate} from '$app/navigation';
  import {feedbackCategories,feedbackStatuses,feedbackPriorities,feedbackStepLabel,feedbackPage} from '@schubert/contracts';
  import {command,displayTimestamp} from '#lib/client/api.ts';
  import type {AppData,Row} from '#lib/client/types.ts';
  import Icon from './Icon.svelte';
  let {data}:{data:AppData}=$props();
  const queue=$derived(data.feedback??{items:[],counts:[],detail:null,next:null,status:'all'});
  const report=$derived(queue.detail);
  let enabled=$state(untrack(()=>!!data.summary.feedback?.enabled)),busy=$state(false),error=$state(''),notice=$state('');
  let messageArea=$state<'setting'|'report'>('setting'),messageReportId=$state('');
  let status=$state(untrack(()=>data.feedback?.detail?.status??'new')),priority=$state(untrack(()=>data.feedback?.detail?.priority??'normal')),notes=$state(untrack(()=>data.feedback?.detail?.admin_notes??'')),resolution=$state(untrack(()=>data.feedback?.detail?.resolution_ref??''));
  $effect(()=>{enabled=!!data.summary.feedback?.enabled;});
  $effect(()=>{if(report){status=report.status;priority=report.priority;notes=report.admin_notes;resolution=report.resolution_ref;}});
  function url(values:Record<string,string|null>){const query=new URLSearchParams(page.url.search);query.set('tab','feedback');for(const [key,value]of Object.entries(values))value?query.set(key,value):query.delete(key);return '/settings?'+query.toString();}
  async function saveSetting(event:SubmitEvent){event.preventDefault();if(busy)return;messageArea='setting';busy=true;error='';notice='';try{await command('feedback.settings.update',undefined,{enabled},data.summary.feedback.version);await refreshAll();notice=enabled?'Feedback ist eingeschaltet. Der Button erscheint auf den internen Seiten.':'Feedback ist ausgeschaltet. Gespeicherte Rückmeldungen bleiben verfügbar.';}catch(e){error=e instanceof Error?e.message:'Einstellung konnte nicht gespeichert werden.';}finally{busy=false;}}
  async function saveReport(event:SubmitEvent){event.preventDefault();if(busy||!report)return;messageArea='report';messageReportId=report.id;busy=true;error='';notice='';try{await command('feedback.update',report.id,{status,priority,admin_notes:notes,resolution_ref:resolution},report.version);await refreshAll();notice=report.number+' wurde aktualisiert.';}catch(e){error=e instanceof Error?e.message:'Rückmeldung konnte nicht aktualisiert werden.';}finally{busy=false;await tick();document.getElementById('feedback-save-notice')?.focus();}}
  const count=$derived(queue.counts.reduce((sum:number,r:Row)=>sum+Number(r.count),0));
  const dirty=$derived(!!report&&(status!==report.status||priority!==report.priority||notes!==report.admin_notes||resolution!==report.resolution_ref));
  beforeNavigate(event=>{if(dirty&&!busy&&!window.confirm('Ihre Einordnung wurde noch nicht gespeichert. Möchten Sie diese Änderungen verwerfen?'))event.cancel();});
</script>

<section class="feedback-admin" data-feedback-private aria-labelledby="feedback-admin-title">
  <div class="feedback-heading"><div><h2 id="feedback-admin-title">Rückmeldungen aus dem Testbetrieb</h2><p>Hinweise verstehen, einordnen und gezielt verbessern. Nur für Sie als Superadmin sichtbar.</p></div><span class="feedback-count">{count} {count===1?'Rückmeldung':'Rückmeldungen'}</span></div>
  <form class="feedback-switch" onsubmit={saveSetting}><div><label class="check-field"><input type="checkbox" bind:checked={enabled} disabled={busy}/><span>Feedback-Button für das Team anzeigen</span></label><p>Aktuell <strong>{data.summary.feedback?.enabled?'eingeschaltet':'ausgeschaltet'}</strong>. Auf bereits geöffneten Seiten wird die Änderung beim nächsten Laden sichtbar. Neue Einsendungen werden beim Ausschalten sofort gesperrt.</p></div><button class="btn" disabled={busy||enabled===!!data.summary.feedback?.enabled}>{busy?'Wird gespeichert …':'Einstellung speichern'}</button></form>
  {#if error&&messageArea==='setting'}<div class="notice error" role="alert"><div>{error}<button class="btn small mt" onclick={()=>refreshAll()}>Aktuellen Stand laden</button></div></div>{/if}
  {#if notice&&messageArea==='setting'}<div class="notice info" role="status">{notice}</div>{/if}
  <div class="feedback-inbox" class:has-selection={!!report}>
    <section class="feedback-list" aria-label="Rückmeldungen auswählen">
      <div class="feedback-filter field"><label for="feedback-filter-status">Status filtern</label><select id="feedback-filter-status" value={queue.status} disabled={busy} onchange={e=>goto(url({status:e.currentTarget.value,cursor:null,report:null}))}><option value="all">Alle Rückmeldungen ({count})</option>{#each Object.entries(feedbackStatuses) as [value,label]}<option {value}>{label} ({queue.counts.find((r:Row)=>r.status===value)?.count??0})</option>{/each}</select><button class="btn small" disabled={busy} onclick={()=>goto(url({refresh:Date.now().toString(),cursor:null}))}><Icon name="refresh" size={15}/>Liste aktualisieren</button></div>
      {#if !queue.items.length}<div class="feedback-empty"><Icon name="pen" size={28}/><h3>{count?'Keine Rückmeldung für diesen Filter':'Hier kommen die Hinweise Ihres Teams an.'}</h3><p>{count?'Wählen Sie einen anderen Status oder öffnen Sie die Liste von Beginn an.':'Schalten Sie den Feedback-Button ein. Das Team kann dann auf jeder internen Seite einen Kommentar hinterlassen.'}</p>{#if count}<a class="btn small" href={url({status:'all',cursor:null,report:null})}>Alle anzeigen</a>{/if}</div>{/if}
      <ul>{#each queue.items as item}<li><a class="feedback-row" class:selected={report?.id===item.id} aria-current={report?.id===item.id?'true':undefined} href={url({report:item.id})}><div class="feedback-row-top"><strong>{item.number}</strong><span>{feedbackStatuses[item.status as keyof typeof feedbackStatuses]}</span></div><p>{item.preview}{item.preview.length===180?'…':''}</p><div class="feedback-row-meta"><span>{item.page_label}</span><span>{displayTimestamp(item.created_at)}</span></div>{#if item.priority!=='normal'}<span class="feedback-priority">Priorität: {feedbackPriorities[item.priority as keyof typeof feedbackPriorities]}</span>{/if}</a></li>{/each}</ul>
      {#if queue.next||page.url.searchParams.has('cursor')}<nav class="feedback-pagination" aria-label="Weitere Rückmeldungen">{#if page.url.searchParams.has('cursor')}<a class="btn small" href={url({cursor:null,report:null})}>Zum Anfang</a>{/if}{#if queue.next}<a class="btn small" href={url({cursor:queue.next,report:null})}>Nächste 25<Icon name="arrow" size={15}/></a>{/if}</nav>{/if}
    </section>
    {#if report}<article class="feedback-detail" aria-labelledby="feedback-report-title">
      <a class="btn small feedback-back" href={url({report:null})}><Icon name="back" size={16}/>Zur Liste</a>
      <header><div><h3 id="feedback-report-title">{report.number} · {feedbackCategories[report.category as keyof typeof feedbackCategories]}</h3><p>{report.submitter_name} · {displayTimestamp(report.created_at)}</p></div><a class="icon-button" href={url({report:null})} aria-label="Rückmeldung schließen"><Icon name="close"/></a></header>
      <p class="feedback-location"><Icon name="file" size={16}/><a class="text-link" href={feedbackPage(report.page_path).path}>{report.page_label} öffnen<Icon name="arrow" size={14}/></a></p>
      <section class="feedback-original"><h4>Kommentar</h4><p>{report.message}</p>{#if report.expected}<h4>Gewünschtes Verhalten</h4><p>{report.expected}</p>{/if}</section>
      <details class="feedback-history" open><summary>Vorherige Bedienschritte ({report.context?.steps?.length??0})</summary>{#if report.context}<p class="small muted">Bis zu 15 Minuten vor dem Öffnen des Feedback-Dialogs. Eine Hilfe zur Fehlersuche; kein vollständiges Nutzungsprotokoll.</p><ol>{#each report.context.steps as step}<li><strong>{feedbackStepLabel(step)}</strong><small>{step.age_seconds} s zuvor · {feedbackPage(step.page).label}</small>{#if step.error_code}<code>{step.error_code}</code>{/if}{#if step.correlation_id}<small>Vorgang: {step.correlation_id}</small>{/if}</li>{/each}</ol>{#if !report.context.steps.length}<p class="small">Keine vorherigen Schritte erfasst.</p>{/if}{:else}<p class="small">Die Person hat keine Bedienschritte mitgesendet.</p>{/if}</details>
      <details class="feedback-technical"><summary>Technischer Kontext</summary><dl><div><dt>Seite</dt><dd>{report.page_path}</dd></div><div><dt>Browser / System</dt><dd>{report.context?report.context.browser+' / '+report.context.os:'Nicht mitgesendet'}</dd></div>{#if report.context}<div><dt>Bildschirmbereich</dt><dd>{report.context.viewport.width} × {report.context.viewport.height} px</dd></div><div><dt>App im Browser</dt><dd>{report.context.client_release}</dd></div>{/if}<div><dt>App auf dem Server</dt><dd>{report.server_release}</dd></div></dl></details>
      <form class="feedback-triage" onsubmit={saveReport}><h4>Ihre Einordnung</h4><div class="field-grid"><div class="field"><label for="feedback-status">Bearbeitungsstatus</label><select id="feedback-status" bind:value={status} disabled={busy}>{#each Object.entries(feedbackStatuses) as [value,label]}<option {value}>{label}</option>{/each}</select></div><div class="field"><label for="feedback-priority">Priorität</label><select id="feedback-priority" bind:value={priority} disabled={busy}>{#each Object.entries(feedbackPriorities) as [value,label]}<option {value}>{label}</option>{/each}</select></div></div><div class="field"><label for="feedback-notes">Notizen zur Umsetzung</label><textarea id="feedback-notes" bind:value={notes} maxlength="5000" rows="4" disabled={busy} placeholder="Gewünschte Änderung, offene Fragen und Abnahmekriterien"></textarea></div><div class="field"><label for="feedback-resolution">Nachweis der Lösung <span class="muted">· optional</span></label><input id="feedback-resolution" bind:value={resolution} maxlength="500" disabled={busy} placeholder="Zum Beispiel: geprüfte Version oder Änderungsreferenz"/></div>{#if messageArea==='report'&&messageReportId===report.id&&(error||notice)}<div id="feedback-save-notice" tabindex="-1" class="notice" class:error={!!error} class:info={!error} role={error?'alert':'status'}><div>{error||notice}{#if error}<p class="small">Ihre Eingaben bleiben erhalten. Bitte erneut speichern. Bei einem zwischenzeitlich geänderten Stand zuerst die eigenen Notizen sichern.</p><button class="btn small mt" type="button" onclick={()=>refreshAll()}>Gespeicherten Stand neu laden</button>{/if}</div></div>{/if}<button class="btn primary" disabled={busy}>{busy?'Wird gespeichert …':'Einordnung speichern'}</button></form>
      <section class="feedback-handoff"><h4>Für die Umsetzung vorbereiten</h4><p>Das Paket enthält den Originalkommentar, Ihre gespeicherte Einordnung, Seiten- und Aktionskontext sowie eine Prüfliste. Eine Umsetzung startet erst auf Ihren ausdrücklichen Auftrag.</p><div class="inline-actions"><a class="btn small" href={'/api/v1/feedback/'+report.id+'/export?format=markdown'} download><Icon name="download" size={16}/>Arbeitsauftrag herunterladen</a><a class="btn small" href={'/api/v1/feedback/'+report.id+'/export'} download>JSON herunterladen</a></div></section>
    </article>{:else}<div class="feedback-selection"><Icon name="file" size={32}/><h3>Ein Hinweis. Sein ganzer Kontext.</h3><p>Wählen Sie eine Rückmeldung aus. Hier sehen Sie den Kommentar, die betroffene Seite und die zuvor ausgeführten Bedienschritte.</p></div>{/if}
  </div>
</section>

<style>
  .feedback-back{display:none}@media(max-width:1000px){.feedback-inbox.has-selection .feedback-list{display:none}.feedback-back{display:inline-flex;margin-bottom:24px}}
  .feedback-admin{max-width:1200px}.feedback-heading{display:flex;justify-content:space-between;align-items:flex-start;gap:20px;margin-bottom:24px}.feedback-heading h2{font-size:23px;letter-spacing:-.025em;margin:0 0 10px}.feedback-heading p{font-size:14px;line-height:1.6;max-width:65ch;color:var(--muted);margin:0}.feedback-count{font-size:12px;white-space:nowrap;padding-top:6px;font-variant-numeric:tabular-nums}.feedback-switch{display:flex;justify-content:space-between;align-items:center;gap:24px;border-block:1px solid var(--line);padding:22px 0;margin-bottom:28px}.feedback-switch p{max-width:73ch;font-size:12px;line-height:1.65;color:var(--muted);margin:10px 0 0}.feedback-switch>.btn{flex-shrink:0}.feedback-inbox{display:grid;grid-template-columns:minmax(280px,.8fr) minmax(0,1.4fr);gap:32px;margin-top:24px}.feedback-filter{margin-bottom:18px}.feedback-list{min-width:0}.feedback-list ul{list-style:none;padding:0;margin:0}.feedback-row{display:block;color:var(--ink);border-bottom:1px solid var(--line);padding:18px 14px;text-decoration:none;overflow-wrap:anywhere}.feedback-row.selected{background:var(--wash);box-shadow:inset 0 0 0 1px var(--forest);border-radius:8px;border-bottom-color:transparent}.feedback-row:hover{background:var(--wash)}.feedback-row-top{display:flex;justify-content:space-between;gap:12px;font-size:12px}.feedback-row-top>span{color:var(--muted)}.feedback-row p{font-size:14px;line-height:1.6;margin:10px 0}.feedback-row-meta{display:flex;flex-wrap:wrap;gap:5px 12px;color:var(--muted);font-size:11px;line-height:1.6}.feedback-priority{display:inline-block;margin-top:8px;font-size:11px;font-weight:600}.feedback-empty,.feedback-selection{padding:40px 20px;color:var(--muted)}.feedback-empty h3,.feedback-selection h3{font-size:18px;line-height:1.4;color:var(--ink);margin:16px 0 10px}.feedback-empty p,.feedback-selection p{font-size:14px;line-height:1.7;max-width:48ch}.feedback-selection{border-left:1px solid var(--line);padding:48px 32px}.feedback-pagination{display:flex;gap:10px;justify-content:space-between;margin-top:20px;flex-wrap:wrap}.feedback-detail{min-width:0;border-left:1px solid var(--line);padding-left:32px;overflow-wrap:anywhere}.feedback-detail header{display:flex;align-items:flex-start;justify-content:space-between;gap:16px}.feedback-detail h3{font-size:22px;letter-spacing:-.02em;line-height:1.3;margin:0}.feedback-detail header p{font-size:12px;color:var(--muted);line-height:1.6;margin:8px 0}.feedback-location{display:flex;gap:8px;align-items:center;font-size:13px;margin:16px 0 28px}.feedback-detail h4{font-size:14px;margin:0 0 12px}.feedback-original p{white-space:pre-wrap;line-height:1.75;font-size:14px;margin:0 0 28px;max-width:72ch}.feedback-detail details{padding:16px 0;border-top:1px solid var(--line)}.feedback-detail summary{font-size:13px;cursor:pointer;line-height:1.6}.feedback-history ol{padding-left:20px;margin:18px 0 0}.feedback-history li{font-size:12px;padding:6px 0;line-height:1.7}.feedback-history small{display:block;color:var(--muted)}.feedback-history strong{font-weight:500}.feedback-technical dl{font-size:12px;line-height:1.7;margin:16px 0 0}.feedback-technical dl>div{display:grid;grid-template-columns:140px 1fr;gap:16px;margin-bottom:8px}.feedback-technical dt{color:var(--muted)}.feedback-technical dd{margin:0}.feedback-triage{border-top:1px solid var(--line);padding-top:28px;display:grid;gap:18px}.feedback-triage h4{margin:0}.feedback-triage>.btn{justify-self:start}.feedback-handoff{margin-top:32px;padding-top:24px;border-top:1px solid var(--line)}.feedback-handoff p{font-size:13px;line-height:1.7;color:var(--muted);max-width:70ch}
  @media(max-width:1000px){.feedback-inbox{grid-template-columns:1fr;gap:28px}.feedback-detail,.feedback-selection{border-left:0;border-top:1px solid var(--line);padding:28px 0 0}.feedback-switch{align-items:flex-start;flex-direction:column;gap:16px}.feedback-heading{display:block}.feedback-count{display:block;margin-top:14px}}@media(max-width:760px){.feedback-heading h2{font-size:21px}.feedback-technical dl>div{grid-template-columns:1fr;gap:0}.feedback-detail .field-grid{grid-template-columns:1fr}.feedback-row{padding:18px 10px}.feedback-handoff .inline-actions{flex-direction:column;align-items:stretch}.feedback-handoff .btn{min-height:46px}}
</style>
